#!/usr/bin/env python3
# Pinneberg-Empfangsfix 2: rtl_fm | sox | minimodem -f -. Kein Pulse.
# Kein Mesh, keine Abschaltung, keine Firewall. Airspy, Stick 1 und Stick 2 bleiben.
from __future__ import annotations
import base64, hashlib, os, shutil, sys
from datetime import datetime
from pathlib import Path

DASH = Path("/home/fmg/prepper-dashboard")
PI = {
    "dashboard.py": ("239bdf4d0f761325", 1392013),
    "blackout_radar.py": ("4ff38da718afed9d", 84127),
    "lage_pages.py": ("e9ea014b5a4ff121", 230936),
}
RX_BASIS = ("a266ddb5ab433981", 17641)
SDR_BASIS = ("e21a0a644a3fc6e3", 777297)
CHECK = ("dashboard.py", "blackout_radar.py", "lage_pages.py", "prepper_sdr.py")


def load():
    raw = PAYLOAD_JSON
    return base64.b64decode(raw["old"]), base64.b64decode(raw["new"])


def sha(data: bytes) -> str:
    return hashlib.sha256(data).hexdigest()


def fenster(now=None):
    from zoneinfo import ZoneInfo
    jetzt = now or datetime.now(ZoneInfo("Europe/Berlin"))
    m = jetzt.minute
    return (not (m >= 45 or m <= 4)), "Berlin Minute %02d" % m


def sichern(path: Path, data: bytes):
    stempel = datetime.now().astimezone().strftime("%Y%m%dT%H%M%S")
    alt = sorted(path.parent.glob(path.name + ".bak-pnfix2-*"))
    bak = path.with_name(path.name + ".bak-pnfix2-" + stempel)
    shutil.copy2(path, bak)
    if bak.read_bytes() != data:
        bak.unlink()
        raise RuntimeError("Sicherung weicht ab")
    for alt_pfad in alt[:-2]:
        try:
            alt_pfad.unlink()
        except OSError:
            pass


def schreiben(path: Path, data: bytes):
    mode = path.stat().st_mode & 0o777
    tmp = path.with_name("." + path.name + ".tmp-pnfix2")
    if tmp.exists():
        raise RuntimeError("temporaere Datei existiert")
    try:
        with open(tmp, "wb") as handle:
            handle.write(data)
            handle.flush()
            os.fsync(handle.fileno())
        os.chmod(tmp, mode)
        os.replace(tmp, path)
    finally:
        if tmp.exists():
            try:
                tmp.unlink()
            except OSError:
                pass


def apply_dir(ordner: Path, dry: bool, kein: bool, jetzt=None) -> int:
    alt, neu = load()
    erwartet = dict(PI)
    erwartet["prepper_sdr.py"] = SDR_BASIS
    falsch = False
    blobs = {}
    for name in ("pinneberg_rx.py",) + CHECK:
        pfad = ordner / name
        if pfad.is_symlink() or not pfad.is_file():
            print("STOP: %s fehlt" % name)
            return 2
        data = pfad.read_bytes()
        blobs[name] = data
        ist = sha(data)
        print("%s sha16 %s bytes %d" % (name, ist[:16], len(data)))
        if name == "pinneberg_rx.py":
            continue
        kopf, laenge = erwartet[name]
        if not ist.startswith(kopf) or len(data) != laenge:
            print("STOP: %s %s / %d ist nicht der Pi-Stand %s / %d" % (name, ist[:16], len(data), kopf, laenge))
            falsch = True
    if falsch:
        print("STOP: Hash-Guard. Nichts geschrieben.")
        return 2
    rx = blobs["pinneberg_rx.py"]
    if rx == neu:
        ziel = rx
    elif rx == alt:
        ziel = neu
    else:
        print("STOP: pinneberg_rx.py %s / %d passt nicht zum installierten Stand %s / %d. Nichts geschrieben." % (sha(rx)[:16], len(rx), RX_BASIS[0], RX_BASIS[1]))
        return 2
    try:
        compile(ziel, "pinneberg_rx.py", "exec")
    except SyntaxError as exc:
        print("STOP: Syntax %s" % exc)
        return 2
    if b'"-f", "-"' not in ziel or b"sox_argv" not in ziel or b" -t wav " not in ziel and b'"-t", "wav"' not in ziel:
        print("STOP: Pipe-Kette fehlt")
        return 2
    print("pinneberg_rx.py endstand sha16 %s bytes %d" % (sha(ziel)[:16], len(ziel)))
    for name in CHECK:
        print("%s unveraendert sha16 %s bytes %d" % (name, sha(blobs[name])[:16], len(blobs[name])))
    frei, meldung = fenster(jetzt)
    print(meldung)
    if rx == ziel:
        print("bereits installiert, keine Aenderung, kein Neustart")
        return 0
    if dry:
        print("DRY-RUN: kein Backup, kein Schreiben, kein Neustart")
        if not frei:
            print("Ein echtes Apply wuerde in dieser Minute ohne Aenderung abbrechen.")
        print("Nach dem Einspielen: systemctl restart prepper-sdr.service")
        print("Pruefung: journalctl -u prepper-sdr.service -n 40 --no-pager | grep pinneberg")
        return 0
    if not frei:
        print("STOP: Neustart-Sperre Minute 45-59 und 00-04 Berlin. Nichts geschrieben.")
        return 2
    try:
        sichern(ordner / "pinneberg_rx.py", rx)
        schreiben(ordner / "pinneberg_rx.py", ziel)
    except (OSError, RuntimeError) as exc:
        print("STOP beim Schreiben: %s" % exc)
        return 3
    print("geschrieben. prepper-sdr muss neu starten. Dashboard, Mesh und Firewall bleiben.")
    if kein:
        print("Kein Neustart in dieser Pruefung. Danach, ausserhalb Minute 45-59 und 00-04: systemctl restart prepper-sdr.service")
        print("Pruefung: journalctl -u prepper-sdr.service -n 40 --no-pager | grep pinneberg")
        return 0
    frei, meldung = fenster()
    print(meldung)
    if not frei:
        print("STOP: Datei ist neu, der Neustart bleibt in der Sperre aus.")
        return 2
    __import__("subprocess").run(["systemctl", "restart", "prepper-sdr.service"], check=False)
    print("Nur prepper-sdr.service neu gestartet.")
    print("Pruefung: journalctl -u prepper-sdr.service -n 40 --no-pager | grep pinneberg")
    return 0


def selftest() -> int:
    global SDR_BASIS
    assert PI["dashboard.py"] == ("239bdf4d0f761325", 1392013)
    assert PI["blackout_radar.py"] == ("4ff38da718afed9d", 84127)
    assert PI["lage_pages.py"] == ("e9ea014b5a4ff121", 230936)
    assert RX_BASIS == ("a266ddb5ab433981", 17641)
    assert SDR_BASIS == ("e21a0a644a3fc6e3", 777297)
    assert fenster(datetime(2026, 11, 20, 20, 12))[0]
    assert not fenster(datetime(2026, 11, 20, 20, 45))[0]
    assert not fenster(datetime(2026, 11, 20, 20, 0))[0]
    assert not fenster(datetime(2026, 11, 20, 20, 4))[0]
    assert fenster(datetime(2026, 11, 20, 20, 5))[0]
    alt, neu = load()
    assert sha(alt).startswith(RX_BASIS[0]) and len(alt) == RX_BASIS[1]
    assert b'"-f", "-"' in neu and b"sox_argv" in neu and b"subprocess.DEVNULL" not in neu
    import tempfile
    ordner = Path(tempfile.mkdtemp(prefix="pnfix2-"))
    (ordner / "pinneberg_rx.py").write_bytes(alt)
    for name in CHECK:
        (ordner / name).write_bytes(b"falsch")
    vorher = {name: (ordner / name).read_bytes() for name in ("pinneberg_rx.py",) + CHECK}
    assert apply_dir(ordner, True, True, datetime(2026, 11, 20, 20, 12)) == 2
    assert vorher == {name: (ordner / name).read_bytes() for name in vorher}
    merk_pi, merk_sdr = dict(PI), SDR_BASIS
    try:
        for name in ("dashboard.py", "blackout_radar.py", "lage_pages.py"):
            teil = b"basis-" + name.encode()
            blob = (teil * (merk_pi[name][1] // len(teil) + 1))[:merk_pi[name][1]]
            (ordner / name).write_bytes(blob)
            PI[name] = (sha(blob)[:16], len(blob))
        sdr = b"prepper-sdr-unveraendert"
        (ordner / "prepper_sdr.py").write_bytes(sdr)
        SDR_BASIS = (sha(sdr)[:16], len(sdr))
        assert apply_dir(ordner, True, True, datetime(2026, 11, 20, 20, 50)) == 0
        assert (ordner / "pinneberg_rx.py").read_bytes() == alt
        assert apply_dir(ordner, False, True, datetime(2026, 11, 20, 20, 2)) == 2
        assert (ordner / "pinneberg_rx.py").read_bytes() == alt
        assert apply_dir(ordner, False, True, datetime(2026, 11, 20, 20, 10)) == 0
        assert (ordner / "pinneberg_rx.py").read_bytes() == neu
        assert (ordner / "prepper_sdr.py").read_bytes() == sdr
        assert list(ordner.glob("pinneberg_rx.py.bak-pnfix2-*"))
        assert apply_dir(ordner, False, True, datetime(2026, 11, 20, 20, 10)) == 0
    finally:
        PI.clear()
        PI.update(merk_pi)
        SDR_BASIS = merk_sdr
    print("selftest ok")
    return 0


def main(argv):
    args = argv[1:]
    dry = kein = False
    wurzel = DASH
    i = 0
    while i < len(args):
        a = args[i]
        if a == "--dry-run":
            dry = True
        elif a == "--kein-neustart":
            kein = True
        elif a == "--selftest":
            return selftest()
        elif a == "--wurzel":
            i += 1
            wurzel = Path(args[i])
        else:
            print("STOP: unbekanntes Argument")
            return 2
        i += 1
    return apply_dir(wurzel, dry, kein)


PAYLOAD_JSON = {"old": "", "new": ""}


if __name__ == "__main__":
    raise SystemExit(main(sys.argv))
